-- Indice da copia conferida no balde 'arena-publico'. Gerado por
-- scripts/arena-subir-copia.mjs. Cada linha aponta para o arquivo IMUTAVEL que
-- foi ao ar, e nunca para a pasta viva do aluno.
delete from public.arena_projeto_midia
 where projeto_id in (select id from public.arena_projeto
                       where edicao_id = (select id from public.arena_edicao where nome like 'TESTE%'));


select tipo, count(*) as arquivos, pg_size_pretty(sum(bytes)) as total
  from public.arena_projeto_midia group by tipo order by tipo;
